def _key(entry):
    return (entry.date, entry.memo, tuple(sorted((line.account, line.cents) for line in entry.lines)))


def import_into(journal, text):
    """Post every entry of `text` not already in `journal`: (imported,
    skipped)."""
    have = {_key(e) for e in journal.entries}
    imported = skipped = 0
    for e in read_csv(text):
        if _key(e) in have:
            skipped += 1
            continue
        journal.post(e)
        have.add(_key(e))
        imported += 1
    return imported, skipped
